 | source={{w|Louis Pergaud}}, ''[[s:La Disparition mystérieuse|La Disparition mystérieuse]]'', dans ''{{w|Les Rustiques, nouvelles villageoises}}'', 1921}}
#* {{exemple | lang=fr
