 | lang=fr
 | source={{w|Marcel Proust}}, ''{{w|Sodome et Gomorrhe (Proust)|Sodome et Gomorrhe}}'', Gallimard, Paris, 1921, page 73.|lien=https://fr.wikisource.org/wiki/Sodome_et_Gomorrhe/Partie_2_-_chapitre_1#73}}
